pts=scan()
# keep points outside body: r>0.25 (body is <0.2 now per az bins) 
P=[(x,y,z) for x,y,z in pts if math.hypot(x,y)>0.25]
# simple grid clustering, cell 0.15m
cell={}
for x,y,z in P:
    cell.setdefault((round(x/0.15),round(y/0.15)),[]).append((x,y,z))
seen=set(); comps=[]
for c in list(cell):
    if c in seen: continue
    stack=[c]; comp=[]
    while stack:
        cur=stack.pop()
        if cur in seen or cur not in cell: continue
        seen.add(cur); comp+=cell[cur]
        cx,cy=cur
        for dx in(-1,0,1):
            for dy in(-1,0,1): stack.append((cx+dx,cy+dy))
    if len(comp)>10: comps.append(comp)
